import openpyxl
wb = openpyxl.load_workbook('gdp.xlsx')
for sheetname in wb.sheetnames:
    sheet = wb[sheetname]
    for r in range(1, sheet.max_row + 1):
        for c in range(1, sheet.max_column + 1):
            if 'NE.RSB.GNFS.ZS' in str(sheet.cell(row=r, column=c).value):
                print(f'Found in {sheetname} at {sheet.cell(row=r, column=c).coordinate}')
